<?php
declare(strict_types=1);
require_once __DIR__ . '/access.php'; require_role('admin'); require_once __DIR__ . '/activity.php';
$message = null; $error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); try { $clientId = (int) ($_POST['client_id'] ?? 0); $employeeId = (int) ($_POST['assigned_to'] ?? 0); $title = trim((string) ($_POST['title'] ?? '')); $description = trim((string) ($_POST['description'] ?? '')); $dueDate = (string) ($_POST['due_date'] ?? '') ?: null; if (!$clientId || !$employeeId || !$title) { throw new RuntimeException('Client, employee, and title are required.'); } db()->prepare('INSERT INTO tasks (client_id, assigned_to, assigned_by, title, description, due_date) VALUES (?, ?, ?, ?, ?, ?)')->execute([$clientId, $employeeId, $_SESSION['user']['id'], $title, $description ?: null, $dueDate]); log_activity((int) $_SESSION['user']['id'], 'Assigned task', 'task', (int) db()->lastInsertId()); $message = 'Task assigned.'; } catch (Throwable $e) { $error = $e->getMessage(); } }
$clients = db()->query('SELECT id, name FROM clients WHERE active = 1 ORDER BY name')->fetchAll(); $employees = db()->query("SELECT id, name FROM users WHERE role = 'employee' AND active = 1 ORDER BY name")->fetchAll(); $tasks = db()->query('SELECT t.*, c.name AS client_name, u.name AS employee_name FROM tasks t INNER JOIN clients c ON c.id = t.client_id INNER JOIN users u ON u.id = t.assigned_to ORDER BY t.created_at DESC LIMIT 30')->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Assign Task</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><div class="d-flex justify-content-between"><h1 class="h3">Assign Task</h1><a href="admin_dashboard.php">Dashboard</a></div><?php if ($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" class="card card-body mb-4"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-4"><label class="form-label">Client</label><select class="form-select" name="client_id" required><option value="">Select</option><?php foreach ($clients as $client): ?><option value="<?= (int) $client['id'] ?>"><?= e($client['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Employee</label><select class="form-select" name="assigned_to" required><option value="">Select</option><?php foreach ($employees as $employee): ?><option value="<?= (int) $employee['id'] ?>"><?= e($employee['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Due date</label><input class="form-control" type="date" name="due_date"></div><div class="col-12"><label class="form-label">Title</label><input class="form-control" name="title" required></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description"></textarea></div><div><button class="btn btn-primary">Assign task</button></div></div></form><div class="card card-body"><h2 class="h5">Recent tasks</h2><table class="table"><thead><tr><th>Task</th><th>Client</th><th>Employee</th><th>Due</th><th>Status</th></tr></thead><tbody><?php foreach ($tasks as $task): ?><tr><td><?= e($task['title']) ?></td><td><?= e($task['client_name']) ?></td><td><?= e($task['employee_name']) ?></td><td><?= e($task['due_date'] ?? '') ?></td><td><?= e(ucwords(str_replace('_', ' ', $task['status']))) ?></td></tr><?php endforeach; ?></tbody></table></div></main></body></html>
